 @Inject(method="getEntityHitResult(Lnet/minecraft/world/entity/Entity;Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/AABB;Ljava/util/function/Predicate;D)Lnet/minecraft/world/phys/EntityHitResult;",at=@At("RETURN"),cancellable=true)
 private static void id01$mesh(Entity source,Vec3 start,Vec3 end,AABB search,Predicate<Entity> predicate,double range,CallbackInfoReturnable<EntityHitResult> ci){var hit=ci.getReturnValue();if(hit!=null&&hit.getEntity() instanceof nl.smartstreamlabs.sbwdroneconfig.Hx2Entity h&&!nl.smartstreamlabs.sbwdroneconfig.Hx2Geometry.ray(h,start,end)){ci.setReturnValue(net.minecraft.world.entity.projectile.ProjectileUtil.getEntityHitResult(source,start,end,search,predicate.and(e->e!=h),range));return;}if(hit!=null&&hit.getEntity() instanceof Qd01Entity q&&!Qd01Geometry.ray(q,start,end)){ci.setReturnValue(net.minecraft.world.entity.projectile.ProjectileUtil.getEntityHitResult(source,start,end,search,predicate.and(e->e!=q),range));return;}if(hit!=null&&hit.getEntity() instanceof Wd01Entity w&&!w.getOBBs().stream().anyMatch(o->o.contains(start)||o.clip(new org.joml.Vector3d(start.x,start.y,start.z),new org.joml.Vector3d(end.x,end.y,end.z)).isPresent())){ci.setReturnValue(net.minecraft.world.entity.projectile.ProjectileUtil.getEntityHitResult(source,start,end,search,predicate.and(e->e!=w),range));return;}if(hit!=null&&hit.getEntity() instanceof Rd01Entity rd&&!Rd01Geometry.ray(rd,start,end)){ci.setReturnValue(net.minecraft.world.entity.projectile.ProjectileUtil.getEntityHitResult(source,start,end,search,predicate.and(e->e!=rd),range));return;}if(hit!=null&&hit.getEntity() instanceof Id01Entity id&&!Id01Geometry.ray(id,start,end))ci.setReturnValue(net.minecraft.world.entity.projectile.ProjectileUtil.getEntityHitResult(source,start,end,search,predicate.and(e->e!=id),range));}
